    func testMatchesReferenceEngine() {
        var compared = 0
        for c in cases {
            let clock = BreathClock(c.config)
            // The technique has to be handed over, not defaulted. Without it the
            // face regions read flat zero and every mouth drawing is invisible —
            // a perfectly legal-looking frame, and caught here only because the
            // fixture was generated by an engine that knew better.
            let profiles = RegionProfiles(
                clock: clock,
                exhalesThroughNose: c.exhalesThroughNose,
                bandha: false,
                hasFace: { phase in phase == .inhale ? c.faceInUsed : c.faceOutUsed })
            for frame in c.frames {
                let transforms = PoseComposer.compose(
                    layers: c.layers,
                    breath: profiles.amounts(at: clock.at(frame.t)),
                    options: PoseOptions(focus: c.focus,
                                         faces: FacePair(inhale: frame.faceIn, exhale: frame.faceOut)))
                let placed = LayerPlacement.place(layers: c.layers,
                                                  transforms: transforms,
                                                  assets: c.assets)
                for (id, x, y, sx, sy, opacity) in frame.placements {
                    guard let p = placed[id] else {
                        XCTFail("\(c.name): nothing placed for \(id)")
                        continue
                    }
                    XCTAssertEqual(p.position.x, x, accuracy: tolerance, "\(c.name) \(id).x at t=\(frame.t)")
                    XCTAssertEqual(p.position.y, y, accuracy: tolerance, "\(c.name) \(id).y at t=\(frame.t)")
                    XCTAssertEqual(p.scale.x, sx, accuracy: tolerance, "\(c.name) \(id).scale.x at t=\(frame.t)")
                    XCTAssertEqual(p.scale.y, sy, accuracy: tolerance, "\(c.name) \(id).scale.y at t=\(frame.t)")
                    XCTAssertEqual(p.opacity, opacity, accuracy: tolerance, "\(c.name) \(id).opacity at t=\(frame.t)")
                    compared += 5
                }
            }
        }
        XCTAssertGreaterThan(compared, 0)
    }

    /// Every drawable layer has an image, and every image belongs to a layer.
    ///
    /// An asset referenced by no layer is indistinguishable from one the
    /// exporter quietly dropped, and a layer with no asset simply does not draw
    /// — which looks like a design decision rather than a missing file.
    func testAssetsAndLayersAgree() {
        for c in cases {
            let drawable = Set(c.layers
                .filter { $0.kind == .mascot || $0.kind == .lid || $0.kind == .mouth }
                .map(\.id))
            let assets = Set(c.assets.keys)
            XCTAssertEqual(drawable.subtracting(assets), [], "\(c.name): layers with no image")
            XCTAssertEqual(assets.subtracting(drawable), [], "\(c.name): images with no layer")
        }
    }

    /// The base layer never moves horizontally away from the composition it was
    /// cut for. It is the whole body, so its crop is the content box — if it
    /// drifted, everything drawn over it would be drawn over the wrong place.
    func testBaseStaysRegistered() {
        for c in cases {
            let clock = BreathClock(c.config)
            // The technique has to be handed over, not defaulted. Without it the
            // face regions read flat zero and every mouth drawing is invisible —
            // a perfectly legal-looking frame, and caught here only because the
            // fixture was generated by an engine that knew better.
            let profiles = RegionProfiles(
                clock: clock,
                exhalesThroughNose: c.exhalesThroughNose,
                bandha: false,
                hasFace: { phase in phase == .inhale ? c.faceInUsed : c.faceOutUsed })
            var seen: [Double] = []
            for frame in c.frames {
                let transforms = PoseComposer.compose(
                    layers: c.layers, breath: profiles.amounts(at: clock.at(frame.t)))
                let placed = LayerPlacement.place(layers: c.layers, transforms: transforms,
                                                  assets: c.assets)
                if let base = placed["base"] { seen.append(base.position.x) }
            }
            guard let lo = seen.min(), let hi = seen.max() else { continue }
            // It does move — the root narrows as it lengthens — but by a
            // fraction of a pixel, not by a body width.
            XCTAssertLessThan(hi - lo, 4, "\(c.name): base drifted \(hi - lo) px")
        }
    }
